 wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 8V5l15-3v3M16 10h5v6h-5a3 3 0 0 1 0-6Z"/><path d="M16 13h.01"/>',
 alert:'<path d="m10.2 4-8 14a2 2 0 0 0 1.7 3h16.2a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.6 0Z"/><path d="M12 9v5m0 3h.01"/>',
 plug:'<path d="m14 3 7 7M6 13l5 5M5 19l-3 3m7-7 7-7M16 2l-4 4 6 6 4-4M2 16l4-4 6 6-4 4Z"/>',
