 search:'<circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 5 5"/>',
 bell:'<path d="M6 8a6 6 0 0 1 12 0c0 7 3 7 3 9H3c0-2 3-2 3-9M10 21h4"/>',
 arrow:'<path d="m9 5 7 7-7 7"/>',
 arrowup:'<path d="m5 16 6-6 4 4 6-10M16 4h5v5"/>',
 refresh:'<path d="M20 7V2l-3 3a9 9 0 1 0 3 12M20 2h-5"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',
 close:'<path d="m6 6 12 12M6 18 18 6"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 check:'<path d="m4 12 5 5L20 6"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',
 download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',
 shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6l8-4Z"/><path d="m8 12 3 3 5-6"/>',
 truck:'<path d="M2 5h12v12H2ZM14 9h4l4 4v4h-8"/><circle cx="6" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',
 watch:'<rect x="6" y="6" width="12" height="12" rx="4"/><path d="M9 6V2h6v4M9 18v4h6v-4M12 9v3l2 1"/>',
 laptop:'<rect x="4" y="4" width="16" height="12" rx="1.5"/><path d="m4 16-3 4h22l-3-4M9 18h6"/>',
 phone:'<rect x="6" y="2" width="12" height="20" rx="2.5"/><path d="M10 5h4m-3 14h2"/>',
 headphones:'<path d="M4 14v-3a8 8 0 0 1 16 0v3"/><rect x="3" y="12" width="4" height="8" rx="2"/><rect x="17" y="12" width="4" height="8" rx="2"/>',
 game:'<path d="M7 7h10c4 0 6 14 2 13l-5-5h-4l-5 5C1 21 3 7 7 7Z"/><path d="M8 9v5m-2-2h4m6-1h.01m2 2h.01"/>',
